import 'dart:convert';

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../../../core/ui/l10n_ext.dart';

/// One bundled package and its license text.
class LicenseEntry {
  const LicenseEntry({
    required this.name,
    required this.version,
    required this.license,
  });

  final String name;
  final String version;
  final String license;
}

/// Loads `assets/licenses.json`, generated by `tool/generate_licenses.dart`.
Future<List<LicenseEntry>> loadBundledLicenses() async {
  final raw = await rootBundle.loadString('assets/licenses.json');
  final decoded = jsonDecode(raw) as List<Object?>;
  return [
    for (final item in decoded.cast<Map<String, Object?>>())
      LicenseEntry(
        name: item['name'] as String,
        version: item['version'] as String,
        license: item['license'] as String,
      ),
  ];
}

/// Third-party notices: searchable list of bundled packages and their licenses.
class LicensesPage extends StatefulWidget {
  const LicensesPage({super.key});

  @override
  State<LicensesPage> createState() => _LicensesPageState();
}

class _LicensesPageState extends State<LicensesPage> {
  late final Future<List<LicenseEntry>> _entries = loadBundledLicenses();
  var _query = '';

  @override
  Widget build(BuildContext context) {
    final l10n = context.l10n;
    final theme = Theme.of(context);
    return Scaffold(
      appBar: AppBar(title: Text(l10n.thirdPartyNotices)),
      body: FutureBuilder<List<LicenseEntry>>(
        future: _entries,
        builder: (context, snapshot) {
          if (snapshot.hasError) {
            return Center(child: Text(l10n.loadFailed));
          }
          final entries = snapshot.data;
          if (entries == null) {
            return const Center(child: CircularProgressIndicator());
          }
          final query = _query.trim().toLowerCase();
          final filtered = query.isEmpty
              ? entries
              : entries
                    .where((e) => e.name.toLowerCase().contains(query))
                    .toList(growable: false);
          return Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 8, 16, 8),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    TextField(
                      decoration: InputDecoration(
                        isDense: true,
                        prefixIcon: const Icon(Icons.search),
                        hintText: l10n.search,
                        border: const OutlineInputBorder(),
                      ),
                      onChanged: (value) => setState(() => _query = value),
                    ),
                    const SizedBox(height: 8),
                    Text(
                      '${l10n.bundledPackages} · ${filtered.length}',
                      style: theme.textTheme.bodySmall?.copyWith(
                        color: theme.colorScheme.onSurfaceVariant,
                      ),
                    ),
                  ],
                ),
              ),
              Expanded(
                child: ListView.separated(
                  itemCount: filtered.length,
                  separatorBuilder: (_, _) => const Divider(height: 1),
                  itemBuilder: (context, index) {
                    final entry = filtered[index];
                    return ExpansionTile(
                      shape: const Border(),
                      collapsedShape: const Border(),
                      leading: CircleAvatar(
                        radius: 16,
                        backgroundColor: theme.colorScheme.secondaryContainer,
                        child: Text(
                          _initial(entry.name),
                          style: theme.textTheme.labelMedium?.copyWith(
                            color: theme.colorScheme.onSecondaryContainer,
                          ),
                        ),
                      ),
                      title: Text(entry.name),
                      subtitle: Text(
                        entry.version,
                        style: theme.textTheme.bodySmall?.copyWith(
                          color: theme.colorScheme.onSurfaceVariant,
                        ),
                      ),
                      childrenPadding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
                      expandedCrossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Container(
                          width: double.infinity,
                          padding: const EdgeInsets.all(12),
                          decoration: BoxDecoration(
                            color: theme.colorScheme.surfaceContainerHighest,
                            borderRadius: BorderRadius.circular(8),
                          ),
                          child: SelectableText(
                            entry.license,
                            style: theme.textTheme.bodySmall?.copyWith(
                              fontFamily: 'monospace',
                            ),
                          ),
                        ),
                      ],
                    );
                  },
                ),
              ),
            ],
          );
        },
      ),
    );
  }

  String _initial(String name) {
    final clean = name.replaceAll(RegExp('[^a-zA-Z0-9]'), '');
    return clean.isEmpty ? '?' : clean[0].toUpperCase();
  }
}
